/** D65 相对光谱功率分布，400–700nm / 10nm（CIE 15:2004，560nm 归一到 100）。 */
const D65 = [
    82.7549, 91.4860, 93.4318, 86.6823, 104.865, 117.008, 117.812, 114.861,
    115.923, 108.811, 109.354, 107.802, 104.790, 107.689, 104.405, 104.046,
    100.000, 96.3342, 95.7880, 88.6856, 90.0062, 89.5991, 87.6987, 83.2886,
    83.6992, 80.0268, 80.2146, 82.2778, 78.2842, 69.7213, 71.6091,
];
/**
 * A 光源（标准照明体 A，2856K 普朗克辐射体）。
 * 按 CIE 定义用普朗克公式解析生成，归一化到 S(560)=100。
 */
function buildIlluminantA() {
    const c2 = 1.435e7; // 第二辐射常数，nm·K（CIE 对 A 光源取 1.435e-2 m·K）
    const T = 2848; // 与 c2=1.435e-2 配套的定义温度
    const planck = (lambdaNm) => {
        const x = c2 / (T * lambdaNm);
        return 1 / (Math.pow(lambdaNm, 5) * (Math.exp(x) - 1));
    };
    const ref = planck(560);
    return WAVELENGTHS.map((l) => (planck(l) / ref) * 100);
}
/**
 * F11（TL84，三基色荧光灯）相对 SPD，400–700nm / 10nm。
 * 特征： continuum 上叠 545nm 与 610nm 附近两条强线谱。
 */
const F11 = [
    4.12, 6.68, 8.29, 14.06, 22.66, 19.31, 16.52, 14.56,
    13.42, 12.87, 13.17, 14.36, 16.55, 19.86, 27.46, 60.46,
    45.55, 34.26, 36.42, 41.52, 56.06, 91.37, 84.76, 56.36,
    28.86, 16.27, 10.26, 7.09, 5.13, 3.90, 3.19,
];
export const ILLUMINANTS = [
    { id: 'D65', name: 'D65 日光', spd: D65 },
    { id: 'A', name: 'A 白炽灯', spd: buildIlluminantA() },
    { id: 'F11', name: 'F11/TL84 商场灯', spd: F11 },
];
export function getIlluminant(id) {
    const found = ILLUMINANTS.find((i) => i.id === id);
    if (!found)
        throw new Error(`未知光源: ${id}`);
    return found;
}
/** 光谱逐点乘（如 反射率 × 光源 SPD）。 */
export function multiply(a, b) {
    const out = new Array(N_BANDS);
    for (let i = 0; i < N_BANDS; i++)
        out[i] = a[i] * b[i];
    return out;
}
/** 光谱均方根误差，用于报告两条反射率曲线的整体差异。 */
export function spectrumRMSE(a, b) {
    let s = 0;
    for (let i = 0; i < N_BANDS; i++) {
        const d = a[i] - b[i];
        s += d * d;
    }
    return Math.sqrt(s / N_BANDS);
}
